<?php
namespace App\Controllers\Gestion;use App\Core\Controller;use App\Core\Request;use App\Core\Session;use App\Models\Inventory;use App\Models\Catalog;use App\Services\InventoryService;use Throwable;
class InventarioController extends Controller{public function index(Request $r):void{(new InventoryService())->ensureDefault(active_environment_id());$m=new Inventory();$this->view('inventario/index',['title'=>'Inventario','inventories'=>$m->inventories(active_environment_id()),'stock'=>$m->stock(active_environment_id()),'movements'=>$m->movements(active_environment_id()),'products'=>$m->products(),'movementTypes'=>(new Catalog())->inventoryMovementTypes(),'productCategories'=>(new Catalog())->productCategories(),'units'=>(new Catalog())->measurementUnits(),'success'=>Session::pullFlash('success'),'error'=>Session::pullFlash('error')]);}public function product(Request $r):void{if(!Session::validateCsrf($r->input('_token'))){http_response_code(419);return;}try{$db=\App\Core\Database::connection();$db->prepare('INSERT INTO productos(categoria_producto_id,codigo,nombre,descripcion,unidad_base_id,controla_lote,controla_vencimiento,activo) VALUES(:c,:co,:n,:d,:u,:l,:v,1)')->execute(['c'=>$r->input('categoria_producto_id')?(int)$r->input('categoria_producto_id'):null,'co'=>strtoupper(trim((string)$r->input('codigo'))),'n'=>trim((string)$r->input('nombre')),'d'=>trim((string)$r->input('descripcion',''))?:null,'u'=>(int)$r->input('unidad_base_id'),'l'=>!empty($r->input('controla_lote'))?1:0,'v'=>!empty($r->input('controla_vencimiento'))?1:0]);Session::flash('success','Producto creado.');}catch(Throwable $e){Session::flash('error',$e->getMessage());}$this->redirect('/inventario');}public function movement(Request $r):void{if(!Session::validateCsrf($r->input('_token'))){http_response_code(419);return;}try{(new InventoryService())->movement($r->all(),active_environment_id(),auth_id());Session::flash('success','Movimiento registrado.');}catch(Throwable $e){Session::flash('error',$e->getMessage());}$this->redirect('/inventario');}}
